import json

# Use the updated transform
def transform_demo_pattern(grid):
    """The pattern implemented in the .py file (matches demo)"""
    rows = len(grid)
    cols = len(grid[0])
    mark1 = mark2 = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1: mark1 = (r, c)
            elif grid[r][c] == 2: mark2 = (r, c)
    mr1, mc1 = mark1; mr2, mc2 = mark2
    out = [[0] * cols for _ in range(rows)]
    out[mr1][mc1] = 1; out[mr2][mc2] = 2

    corner_r, corner_c = mr2 + 1, mc2 - 4

    # Horizontal: 4 cells at row=mark2_row+1, cols=mark2_col-4 to mark2_col-1
    for c in range(corner_c, corner_c + 4):
        if 0 <= corner_r < rows and 0 <= c < cols:
            out[corner_r][c] = 3

    # Diagonal: 5 cells starting from (h_end_row+1, h_end_col-4), going DOWN-LEFT (+1,-1)
    h_end_row, h_end_col = corner_r, corner_c + 3
    diag_start_r, diag_start_c = h_end_row + 1, h_end_col - 4

    for k in range(5):
        r, c = diag_start_r + k, diag_start_c - k  # DOWN-LEFT: (+1, -1)
        if 0 <= r < rows and 0 <= c < cols:
            out[r][c] = 3
    return out

